/**
 * The RealWorld spec models every failure as `{"errors": {"<field>": ["<message>"]}}`.
 * `ApiError` carries that body plus the status code the route wants to answer with.
 */
export type ErrorMap = Record<string, string[]>;

export class ApiError extends Error {
  readonly status: number;
  readonly errors: ErrorMap;

  constructor(status: number, errors: ErrorMap) {
    super(`API error ${status}`);
    this.name = "ApiError";
    this.status = status;
    this.errors = errors;
  }

  toBody(): { errors: ErrorMap } {
    return { errors: this.errors };
  }
}

export const missingToken = () => new ApiError(401, { token: ["is missing"] });
export const invalidToken = () => new ApiError(401, { token: ["is invalid"] });
export const invalidCredentials = () => new ApiError(401, { credentials: ["invalid"] });
export const notFound = (resource: string) => new ApiError(404, { [resource]: ["not found"] });
export const forbidden = (resource: string) => new ApiError(403, { [resource]: ["forbidden"] });
export const unprocessable = (errors: ErrorMap) => new ApiError(422, errors);
export const conflict = (errors: ErrorMap) => new ApiError(409, errors);

