import { type ErrorMap, unprocessable } from "./errors.ts";

export const BLANK = "can't be blank";
export const TAKEN = "has already been taken";
export const INVALID = "is invalid";

/** NIST SP 800-63B 5.1.1.2: memorized secrets are at least 8 characters long. */
export const PASSWORD_MIN_LENGTH = 8;
export const PASSWORD_TOO_SHORT = `is too short (minimum is ${PASSWORD_MIN_LENGTH} characters)`;

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Collects `{field: [messages]}` and raises a single 422 when anything was recorded. */
export class ErrorCollector {
  private readonly errors: ErrorMap = {};

  add(field: string, message: string): void {
    (this.errors[field] ??= []).push(message);
  }

  get isEmpty(): boolean {
    return Object.keys(this.errors).length === 0;
  }

  throwIfAny(): void {
    if (!this.isEmpty) throw unprocessable(this.errors);
  }
}

/** The payload envelope (`{"user": {...}}`) is required and must be an object. */
export function requireEnvelope(body: unknown, key: string): Record<string, unknown> {
  const root = isRecord(body) ? body[key] : undefined;
  if (!isRecord(root)) throw unprocessable({ [key]: [BLANK] });
  return root;
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function has(payload: Record<string, unknown>, field: string): boolean {
  return Object.prototype.hasOwnProperty.call(payload, field);
}

/**
 * Reads a mandatory string: absent, null, non-string and whitespace-only all count as blank.
 * Returns the trimmed value, or `null` when an error was recorded.
 */
export function readRequiredString(
  payload: Record<string, unknown>,
  field: string,
  errors: ErrorCollector,
): string | null {
  const value = payload[field];
  if (typeof value !== "string" || value.trim() === "") {
    errors.add(field, BLANK);
    return null;
  }
  return value.trim();
}

/**
 * Reads an optional nullable string. Absent means "leave untouched" (`undefined`);
 * `null` and `""` both normalize to `null` so the field is cleared.
 */
export function readNullableString(
  payload: Record<string, unknown>,
  field: string,
  errors: ErrorCollector,
): string | null | undefined {
  if (!has(payload, field)) return undefined;
  const value = payload[field];
  if (value === null) return null;
  if (typeof value !== "string") {
    errors.add(field, INVALID);
    return undefined;
  }
  return value.trim() === "" ? null : value;
}

export function validateEmailFormat(email: string, errors: ErrorCollector): void {
  if (!EMAIL_PATTERN.test(email)) errors.add("email", INVALID);
}

export function validatePassword(password: string, errors: ErrorCollector): void {
  if (password.length < PASSWORD_MIN_LENGTH) errors.add("password", PASSWORD_TOO_SHORT);
}

/**
 * Reads a tagList. Absent means "leave untouched"; an explicit `null` is rejected
 * because the spec only allows clearing tags with an empty array.
 */
export function readTagList(
  payload: Record<string, unknown>,
  errors: ErrorCollector,
): string[] | undefined {
  if (!has(payload, "tagList")) return undefined;
  const value = payload.tagList;
  if (!Array.isArray(value)) {
    errors.add("tagList", INVALID);
    return undefined;
  }
  const tags: string[] = [];
  for (const entry of value) {
    if (typeof entry !== "string") {
      errors.add("tagList", INVALID);
      return undefined;
    }
    const tag = entry.trim();
    if (tag !== "" && !tags.includes(tag)) tags.push(tag);
  }
  return tags;
}

/** Parses a non-negative integer query parameter, falling back to `fallback`. */
export function parseNonNegativeInt(raw: unknown, fallback: number): number {
  if (typeof raw !== "string" || raw.trim() === "") return fallback;
  const parsed = Number(raw);
  if (!Number.isInteger(parsed) || parsed < 0) return fallback;
  return parsed;
}

