import jwt from "jsonwebtoken";
import bcrypt from "bcryptjs";
import type { FastifyRequest } from "fastify";
import { config } from "./config.ts";
import { prisma, type User } from "./db.ts";
import { invalidToken, missingToken } from "./errors.ts";

const BCRYPT_ROUNDS = 10;

declare module "fastify" {
  interface FastifyRequest {
    /** Set by `requireAuth`/`optionalAuth`; `null` for anonymous requests. */
    currentUser: User | null;
  }
}

export function hashPassword(password: string): Promise<string> {
  return bcrypt.hash(password, BCRYPT_ROUNDS);
}

export function verifyPassword(password: string, hash: string): Promise<boolean> {
  return bcrypt.compare(password, hash);
}

export function signToken(userId: number): string {
  return jwt.sign({ sub: String(userId) }, config.jwtSecret, {
    expiresIn: config.jwtExpiresIn as jwt.SignOptions["expiresIn"],
  });
}

/** Accepts both the spec's `Token <jwt>` scheme and the more common `Bearer <jwt>`. */
function extractToken(header: string | undefined): string | null {
  if (!header) return null;
  const match = /^(?:Token|Bearer)\s+(.+)$/i.exec(header.trim());
  const token = match?.[1]?.trim();
  return token ? token : null;
}

async function resolveUser(token: string): Promise<User> {
  let payload: jwt.JwtPayload;
  try {
    payload = jwt.verify(token, config.jwtSecret) as jwt.JwtPayload;
  } catch {
    throw invalidToken();
  }
  const userId = Number(payload.sub);
  if (!Number.isInteger(userId)) throw invalidToken();

  const user = await prisma.user.findUnique({ where: { id: userId } });
  if (!user) throw invalidToken();
  return user;
}

/**
 * Registered as an `onRequest` hook so a missing token answers 401 before Fastify
 * parses (and possibly rejects) the request body.
 */
export async function requireAuth(request: FastifyRequest): Promise<void> {
  const token = extractToken(request.headers.authorization);
  if (!token) throw missingToken();
  request.currentUser = await resolveUser(token);
}

/** Anonymous requests are allowed through; a supplied-but-broken token is still a 401. */
export async function optionalAuth(request: FastifyRequest): Promise<void> {
  const token = extractToken(request.headers.authorization);
  request.currentUser = token ? await resolveUser(token) : null;
}

/** Narrowing helper for routes guarded by `requireAuth`. */
export function currentUser(request: FastifyRequest): User {
  if (!request.currentUser) throw missingToken();
  return request.currentUser;
}

