  id: number;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  author: AuthorRecord;
};

export type Profile = {
  username: string;
  bio: string | null;
  image: string | null;
  following: boolean;
};

export function userResponse(user: User, token = signToken(user.id)) {
  return {
    user: {
      email: user.email,
      token,
      username: user.username,
      bio: user.bio,
      image: user.image,
    },
  };
}

export function toProfile(user: Pick<User, "username" | "bio" | "image">, following: boolean): Profile {
  return {
    username: user.username,
    bio: user.bio,
    image: user.image,
    following,
  };
}

export function profileResponse(user: Pick<User, "username" | "bio" | "image">, following: boolean) {
  return { profile: toProfile(user, following) };
}

function authorProfile(author: AuthorRecord): Profile {
  return toProfile(author, author.followers.length > 0);
}

function serializeArticle(article: ArticleRecord, withBody: boolean) {
  return {
    slug: article.slug,
    title: article.title,
    description: article.description,
    ...(withBody ? { body: article.body } : {}),
    tagList: article.tags.map((link) => link.tag.name),
    createdAt: article.createdAt.toISOString(),
    updatedAt: article.updatedAt.toISOString(),
    favorited: article.favorites.length > 0,
    favoritesCount: article._count.favorites,
    author: authorProfile(article.author),
  };
}

export function articleResponse(article: ArticleRecord) {
  return { article: serializeArticle(article, true) };
}

/** List payloads omit `body`; `articlesCount` is the total match count, not the page size. */
export function articlesResponse(articles: ArticleRecord[], articlesCount: number) {
  return {
    articles: articles.map((article) => serializeArticle(article, false)),
    articlesCount,
  };
}

function serializeComment(comment: CommentRecord) {
  return {
    id: comment.id,
    createdAt: comment.createdAt.toISOString(),
    updatedAt: comment.updatedAt.toISOString(),
    body: comment.body,
    author: authorProfile(comment.author),
  };
}

export function commentResponse(comment: CommentRecord) {
  return { comment: serializeComment(comment) };
}

export function commentsResponse(comments: CommentRecord[]) {
  return { comments: comments.map(serializeComment) };
}

