import type { FastifyPluginAsync } from "fastify";
import { currentUser, hashPassword, requireAuth, verifyPassword } from "../auth.ts";
import { prisma } from "../db.ts";
import { conflict, invalidCredentials } from "../errors.ts";
import { userResponse } from "../serializers.ts";
import {
  BLANK,
  ErrorCollector,
  TAKEN,
  has,
  readNullableString,
  readRequiredString,
  requireEnvelope,
  validateEmailFormat,
  validatePassword,
} from "../validation.ts";

/** Registration and update both need to keep `username`/`email` unique across users. */
async function assertUnique(
  fields: { username?: string; email?: string },
  excludeUserId?: number,
): Promise<void> {
  const errors: Record<string, string[]> = {};

  if (fields.username) {
    const existing = await prisma.user.findUnique({ where: { username: fields.username } });
    if (existing && existing.id !== excludeUserId) errors.username = [TAKEN];
  }
  if (fields.email) {
    const existing = await prisma.user.findUnique({ where: { email: fields.email } });
    if (existing && existing.id !== excludeUserId) errors.email = [TAKEN];
  }

  if (Object.keys(errors).length > 0) throw conflict(errors);
}

export const userRoutes: FastifyPluginAsync = async (app) => {
  // POST /api/users — registration
  app.post("/users", async (request, reply) => {
    const payload = requireEnvelope(request.body, "user");
    const errors = new ErrorCollector();

    const username = readRequiredString(payload, "username", errors);
    const email = readRequiredString(payload, "email", errors);
    const password = typeof payload.password === "string" ? payload.password : "";
    if (password === "") errors.add("password", BLANK);

    if (email) validateEmailFormat(email, errors);
    if (password !== "") validatePassword(password, errors);
    errors.throwIfAny();

    await assertUnique({ username: username!, email: email! });

    const user = await prisma.user.create({
      data: {
        username: username!,
        email: email!,
        password: await hashPassword(password),
      },
    });

    return reply.code(201).send(userResponse(user));
  });

  // POST /api/users/login
  app.post("/users/login", async (request) => {
    const payload = requireEnvelope(request.body, "user");
    const errors = new ErrorCollector();

    const email = readRequiredString(payload, "email", errors);
    const password = typeof payload.password === "string" ? payload.password : "";
    if (password === "") errors.add("password", BLANK);
    errors.throwIfAny();

    const user = await prisma.user.findUnique({ where: { email: email! } });
    if (!user || !(await verifyPassword(password, user.password))) throw invalidCredentials();

    return userResponse(user);
  });

  // GET /api/user — the authenticated user
  app.get("/user", { onRequest: requireAuth }, async (request) => userResponse(currentUser(request)));

  // PUT /api/user
  app.put("/user", { onRequest: requireAuth }, async (request) => {
    const user = currentUser(request);
    const payload = requireEnvelope(request.body, "user");
    const errors = new ErrorCollector();

    // `username`/`email`/`password` are non-nullable: sending null or "" is a validation error.
    const username = has(payload, "username") ? readRequiredString(payload, "username", errors) : undefined;
    const email = has(payload, "email") ? readRequiredString(payload, "email", errors) : undefined;

    let password: string | undefined;
    if (has(payload, "password")) {
      const raw = payload.password;
      if (typeof raw !== "string" || raw === "") {
        errors.add("password", BLANK);
      } else {
        validatePassword(raw, errors);
        password = raw;
      }
    }

    // `bio`/`image` are nullable: null and "" both clear the field.
    const bio = readNullableString(payload, "bio", errors);
    const image = readNullableString(payload, "image", errors);

    if (email) validateEmailFormat(email, errors);
    errors.throwIfAny();

    await assertUnique({ username: username ?? undefined, email: email ?? undefined }, user.id);

    const updated = await prisma.user.update({
      where: { id: user.id },
      data: {
        ...(username ? { username } : {}),
        ...(email ? { email } : {}),
        ...(password ? { password: await hashPassword(password) } : {}),
        ...(bio !== undefined ? { bio } : {}),
        ...(image !== undefined ? { image } : {}),
      },
    });

    return userResponse(updated);
  });
};

