import type { FastifyPluginAsync, FastifyRequest } from "fastify";
import { currentUser, optionalAuth, requireAuth } from "../auth.ts";
import { prisma } from "../db.ts";
import { notFound } from "../errors.ts";
import { profileResponse } from "../serializers.ts";

type UsernameParams = { username: string };

async function findProfileOrThrow(username: string) {
  const user = await prisma.user.findUnique({ where: { username } });
  if (!user) throw notFound("profile");
  return user;
}

async function isFollowing(followerId: number | undefined, followedId: number): Promise<boolean> {
  if (!followerId) return false;
  const follow = await prisma.follow.findUnique({
    where: { followerId_followedId: { followerId, followedId } },
  });
  return follow !== null;
}

export const profileRoutes: FastifyPluginAsync = async (app) => {
  // GET /api/profiles/:username
  app.get(
    "/profiles/:username",
    { onRequest: optionalAuth },
    async (request: FastifyRequest<{ Params: UsernameParams }>) => {
      const profile = await findProfileOrThrow(request.params.username);
      const following = await isFollowing(request.currentUser?.id, profile.id);
      return profileResponse(profile, following);
    },
  );

  // POST /api/profiles/:username/follow
  app.post(
    "/profiles/:username/follow",
    { onRequest: requireAuth },
    async (request: FastifyRequest<{ Params: UsernameParams }>) => {
      const me = currentUser(request);
      const profile = await findProfileOrThrow(request.params.username);

      if (profile.id !== me.id) {
        // Following twice is a no-op rather than an error.
        await prisma.follow.upsert({
          where: { followerId_followedId: { followerId: me.id, followedId: profile.id } },
          create: { followerId: me.id, followedId: profile.id },
          update: {},
        });
      }

      return profileResponse(profile, profile.id !== me.id);
    },
  );

  // DELETE /api/profiles/:username/follow
  app.delete(
    "/profiles/:username/follow",
    { onRequest: requireAuth },
    async (request: FastifyRequest<{ Params: UsernameParams }>) => {
      const me = currentUser(request);
      const profile = await findProfileOrThrow(request.params.username);

      await prisma.follow.deleteMany({
        where: { followerId: me.id, followedId: profile.id },
      });

      return profileResponse(profile, false);
    },
  );
};

