async function replaceTags(articleId: number, tags: string[]): Promise<void> {
  await prisma.articleTag.deleteMany({ where: { articleId } });
  for (const [position, name] of tags.entries()) {
    const tag = await prisma.tag.upsert({ where: { name }, create: { name }, update: {} });
    await prisma.articleTag.create({ data: { articleId, tagId: tag.id, position } });
  }
}

/** Guarantees a visibly newer `updatedAt` even when an update lands in the same millisecond. */
function nextUpdatedAt(previous: Date): Date {
  const now = Date.now();
  return new Date(Math.max(now, previous.getTime() + 1));
}

export const articleRoutes: FastifyPluginAsync = async (app) => {
  // GET /api/articles — global feed with tag/author/favorited filters
  app.get(
    "/articles",
    { onRequest: optionalAuth },
    async (request: FastifyRequest<{ Querystring: ListQuery }>) => {
      const { tag, author, favorited } = request.query;
      const viewerId = request.currentUser?.id ?? null;

      const where = {
        ...(tag ? { tags: { some: { tag: { name: tag } } } } : {}),
        ...(author ? { author: { username: author } } : {}),
        ...(favorited ? { favorites: { some: { user: { username: favorited } } } } : {}),
      };

      const [articles, articlesCount] = await Promise.all([
        prisma.article.findMany({
          where,
          include: articleInclude(viewerId),
          orderBy: [{ createdAt: "desc" }, { id: "desc" }],
          take: parseNonNegativeInt(request.query.limit, DEFAULT_LIMIT),
          skip: parseNonNegativeInt(request.query.offset, 0),
        }),
        prisma.article.count({ where }),
      ]);

      return articlesResponse(articles, articlesCount);
    },
  );

  // GET /api/articles/feed — articles from followed authors
  app.get(
    "/articles/feed",
    { onRequest: requireAuth },
    async (request: FastifyRequest<{ Querystring: FeedQuery }>) => {
      const me = currentUser(request);
      const where = { author: { followers: { some: { followerId: me.id } } } };

      const [articles, articlesCount] = await Promise.all([
        prisma.article.findMany({
          where,
          include: articleInclude(me.id),
          orderBy: [{ createdAt: "desc" }, { id: "desc" }],
          take: parseNonNegativeInt(request.query.limit, DEFAULT_LIMIT),
          skip: parseNonNegativeInt(request.query.offset, 0),
        }),
        prisma.article.count({ where }),
      ]);

      return articlesResponse(articles, articlesCount);
    },
  );

  // POST /api/articles
  app.post("/articles", { onRequest: requireAuth }, async (request, reply) => {
    const me = currentUser(request);
    const payload = requireEnvelope(request.body, "article");
    const errors = new ErrorCollector();

    const title = readRequiredString(payload, "title", errors);
    const description = readRequiredString(payload, "description", errors);
    const body = readRequiredString(payload, "body", errors);
    const tagList = readTagList(payload, errors) ?? [];
    errors.throwIfAny();

    const created = await prisma.article.create({
      data: {
        slug: buildSlug(title!),
        title: title!,
        description: description!,
        body: body!,
        authorId: me.id,
      },
    });
    await replaceTags(created.id, tagList);

    return reply.code(201).send(articleResponse(await loadArticle(created.slug, me.id)));
  });

  // GET /api/articles/:slug
  app.get(
    "/articles/:slug",
    { onRequest: optionalAuth },
    async (request: FastifyRequest<{ Params: SlugParams }>) =>
      articleResponse(await loadArticle(request.params.slug, request.currentUser?.id ?? null)),
  );

  // PUT /api/articles/:slug
  app.put(
    "/articles/:slug",
    { onRequest: requireAuth },
    async (request: FastifyRequest<{ Params: SlugParams }>) => {
      const me = currentUser(request);
      const existing = await loadOwnedArticle(request.params.slug, me.id);

      const payload = requireEnvelope(request.body, "article");
      const errors = new ErrorCollector();

      const title = has(payload, "title") ? readRequiredString(payload, "title", errors) : undefined;
      const description = has(payload, "description")
        ? readRequiredString(payload, "description", errors)
        : undefined;
      const body = has(payload, "body") ? readRequiredString(payload, "body", errors) : undefined;
      const tagList = readTagList(payload, errors);
      errors.throwIfAny();

      // The slug stays put so existing links keep resolving after a rename.
      await prisma.article.update({
        where: { id: existing.id },
        data: {
          ...(title ? { title } : {}),
          ...(description ? { description } : {}),
          ...(body ? { body } : {}),
          updatedAt: nextUpdatedAt(existing.updatedAt),
        },
      });
      if (tagList !== undefined) await replaceTags(existing.id, tagList);

      return articleResponse(await loadArticle(existing.slug, me.id));
    },
  );

  // DELETE /api/articles/:slug
  app.delete(
    "/articles/:slug",
    { onRequest: requireAuth },
    async (request: FastifyRequest<{ Params: SlugParams }>, reply) => {
      const me = currentUser(request);
      const article = await loadOwnedArticle(request.params.slug, me.id);
      await prisma.article.delete({ where: { id: article.id } });
      return reply.code(204).send();
    },
  );

  // POST /api/articles/:slug/favorite
  app.post(
    "/articles/:slug/favorite",
    { onRequest: requireAuth },
    async (request: FastifyRequest<{ Params: SlugParams }>) => {
      const me = currentUser(request);
      const article = await loadArticle(request.params.slug, me.id);

      await prisma.favorite.upsert({
        where: { userId_articleId: { userId: me.id, articleId: article.id } },
        create: { userId: me.id, articleId: article.id },
        update: {},
      });

      return articleResponse(await loadArticle(article.slug, me.id));
    },
  );

  // DELETE /api/articles/:slug/favorite
  app.delete(
    "/articles/:slug/favorite",
    { onRequest: requireAuth },
    async (request: FastifyRequest<{ Params: SlugParams }>) => {
      const me = currentUser(request);
      const article = await loadArticle(request.params.slug, me.id);

      await prisma.favorite.deleteMany({ where: { userId: me.id, articleId: article.id } });

      return articleResponse(await loadArticle(article.slug, me.id));
    },
  );
};

