import type { FastifyPluginAsync, FastifyRequest } from "fastify";
import { currentUser, optionalAuth, requireAuth } from "../auth.ts";
import { prisma } from "../db.ts";
import { forbidden, notFound } from "../errors.ts";
import { commentInclude, commentResponse, commentsResponse } from "../serializers.ts";
import { ErrorCollector, readRequiredString, requireEnvelope } from "../validation.ts";

type SlugParams = { slug: string };
type CommentParams = { slug: string; id: string };

async function findArticleOrThrow(slug: string) {
  const article = await prisma.article.findUnique({ where: { slug }, select: { id: true } });
  if (!article) throw notFound("article");
  return article;
}

export const commentRoutes: FastifyPluginAsync = async (app) => {
  // GET /api/articles/:slug/comments
  app.get(
    "/articles/:slug/comments",
    { onRequest: optionalAuth },
    async (request: FastifyRequest<{ Params: SlugParams }>) => {
      const article = await findArticleOrThrow(request.params.slug);
      const viewerId = request.currentUser?.id ?? null;

      const comments = await prisma.comment.findMany({
        where: { articleId: article.id },
        include: commentInclude(viewerId),
        orderBy: { id: "asc" },
      });

      return commentsResponse(comments);
    },
  );

  // POST /api/articles/:slug/comments
  app.post(
    "/articles/:slug/comments",
    { onRequest: requireAuth },
    async (request: FastifyRequest<{ Params: SlugParams }>, reply) => {
      const me = currentUser(request);
      const article = await findArticleOrThrow(request.params.slug);

      const payload = requireEnvelope(request.body, "comment");
      const errors = new ErrorCollector();
      const body = readRequiredString(payload, "body", errors);
      errors.throwIfAny();

      const comment = await prisma.comment.create({
        data: { body: body!, articleId: article.id, authorId: me.id },
        include: commentInclude(me.id),
      });

      return reply.code(201).send(commentResponse(comment));
    },
  );

  // DELETE /api/articles/:slug/comments/:id
  app.delete(
    "/articles/:slug/comments/:id",
    { onRequest: requireAuth },
    async (request: FastifyRequest<{ Params: CommentParams }>, reply) => {
      const me = currentUser(request);
      const article = await findArticleOrThrow(request.params.slug);

      const commentId = Number(request.params.id);
      if (!Number.isInteger(commentId)) throw notFound("comment");

      const comment = await prisma.comment.findFirst({
        where: { id: commentId, articleId: article.id },
      });
      if (!comment) throw notFound("comment");
      if (comment.authorId !== me.id) throw forbidden("comment");

      await prisma.comment.delete({ where: { id: comment.id } });
      return reply.code(204).send();
    },
  );
};

