import cors from "@fastify/cors";
import Fastify, { type FastifyInstance } from "fastify";
import { config } from "./config.ts";
import { ApiError, conflict, notFound, unprocessable } from "./errors.ts";
import { articleRoutes } from "./routes/articles.ts";
import { commentRoutes } from "./routes/comments.ts";
import { profileRoutes } from "./routes/profiles.ts";
import { tagRoutes } from "./routes/tags.ts";
import { userRoutes } from "./routes/users.ts";
import { INVALID, TAKEN } from "./validation.ts";

/** Prisma's unique-constraint failure, mapped to the spec's 409 response. */
function asUniqueConstraintError(error: unknown): ApiError | null {
  if (typeof error !== "object" || error === null) return null;
  if ((error as { code?: string }).code !== "P2002") return null;

  const target = (error as { meta?: { target?: unknown } }).meta?.target;
  const fields = Array.isArray(target) ? target.map(String) : typeof target === "string" ? [target] : [];
  if (fields.length === 0) return conflict({ resource: [TAKEN] });

  return conflict(Object.fromEntries(fields.map((field) => [field, [TAKEN]])));
}

export async function buildApp(): Promise<FastifyInstance> {
  const app = Fastify({
    logger: { level: config.logLevel },
    // Slugs and usernames are case-sensitive identifiers.
    caseSensitive: true,
  });

  await app.register(cors, { origin: true });

  // An absent or empty JSON body is treated as `{}` so validation — not the parser —
  // decides the response; malformed JSON becomes a 422 like any other bad payload.
  app.addContentTypeParser(
    "application/json",
    { parseAs: "string" },
    (_request, body: string, done) => {
      if (!body || body.trim() === "") return done(null, {});
      try {
        done(null, JSON.parse(body));
      } catch {
        done(unprocessable({ body: [INVALID] }), undefined);
      }
    },
  );

  app.get("/health", async () => ({ status: "ok" }));

  await app.register(
    async (api) => {
      await api.register(userRoutes);
      await api.register(profileRoutes);
      await api.register(articleRoutes);
      await api.register(commentRoutes);
      await api.register(tagRoutes);
    },
    { prefix: "/api" },
  );

  app.setNotFoundHandler(async (_request, reply) => {
    const error = notFound("route");
    return reply.code(error.status).send(error.toBody());
  });

  app.setErrorHandler(async (error, request, reply) => {
    const apiError = error instanceof ApiError ? error : asUniqueConstraintError(error);
    if (apiError) {
      return reply.code(apiError.status).send(apiError.toBody());
    }

    // Anything Fastify itself rejected (bad JSON, unsupported media type, ...) is a
    // client-side payload problem, which the spec reports as 422.
    const statusCode = (error as { statusCode?: number }).statusCode ?? 500;
    if (statusCode >= 400 && statusCode < 500) {
      return reply.code(422).send({ errors: { body: [INVALID] } });
    }

    request.log.error({ err: error }, "unhandled error");
    return reply.code(500).send({ errors: { server: ["internal server error"] } });
  });

  return app;
}

